.woocommerce-checkout #payment div.payment_box::before, .woocommerce-checkout #payment .payment_method_paypal .about_paypal, .woocommerce-checkout #payment ul.payment_methods li img, #payment ul.payment_methods li img.stripe-icon {
 display:none !important;   
}
.woocommerce-checkout #payment div.payment_box{
    background:white !important;
}

.woocommerce-checkout #payment div.payment_box{
    margin:0 !important;
    padding:0 !important;
}

.woocommerce #payment #place_order, .woocommerce-page #payment #place_order{
    float:none !important;
}

.woocommerce-checkout #payment div.form-row{
    text-align:center !important;
}

table tbody>tr:nth-child(odd)>td, table tbody tr:hover>td{
    background-color: white !important;
}

.chbs-main .chbs-box-shadow{
    box-shadow:none !important;
}

.chbs-summary{
    background:#ffffff !important;
    border:1px solid #CED3D9;
}

.chbs-main img{
      margin-left: auto;
  margin-right: auto;
}
.chbs-main .chbs-coupon-code-section .chbs-form-field{
    border-color:#CED3D9 !important;
}

.woocommerce #payment #place_order, .woocommerce-page #payment #place_order{
    background-color: #189930 !important;
    color: white !important;
    border-color: #189930 !important;
}
.woocommerce #payment #place_order:hover, .woocommerce-page #payment #place_order:hover{
    background-color: #147F28 !important;
    color: white !important;
    border-color: #147F28 !important;
}

.chbs-tab.ui-tabs .ui-tabs-nav>li.ui-tabs-active>a{background: #58555C !important;
    border-color: #58555C !important
}
html .chbs-booking-form-id-23152 .chbs-tab.ui-tabs .ui-tabs-panel, .chbs-tab.ui-tabs .ui-tabs-nav>li>a, .chbs-booking-form-id-23152 .chbs-tab.ui-tabs .ui-tabs-nav>li.ui-tabs-active+li>a{
    border: none !important;
}
.chbs-main .chbs-tab.ui-tabs .ui-tabs-nav{
    margin-bottom:7px !important;
}

@media (min-width: 1025px) {
.jet-services__content{
    min-height:200px;
}
}
