/* Fix Jet Carousel display without slick.js */
.jet-carousel.elementor-slick-slider {
    display: grid !important;
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
    gap: 24px !important;
    width: 100% !important;
    margin: 20px 0 !important;
}
@media (max-width: 1200px) {
    .jet-carousel.elementor-slick-slider {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    }
}
@media (max-width: 640px) {
    .jet-carousel.elementor-slick-slider {
        grid-template-columns: 1fr !important;
    }
}
.jet-carousel .jet-carousel__item {
    display: block !important;
    float: none !important;
    width: 100% !important;
    min-height: auto !important;
}
.jet-carousel .slick-list {
    overflow: visible !important;
}

/* Trustindex review cards styling */
.ti-widget {
    display: block !important;
    width: 100% !important;
}
.ti-widget .ti-widget-container {
    display: block !important;
}
.ti-widget .ti-reviews-container {
    display: grid !important;
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
    gap: 20px !important;
}
@media (max-width: 1024px) {
    .ti-widget .ti-reviews-container {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    }
}
@media (max-width: 640px) {
    .ti-widget .ti-reviews-container {
        grid-template-columns: 1fr !important;
    }
}
.ti-widget .ti-review-item {
    display: block !important;
    margin-bottom: 20px !important;
}

/* Sticky Header on scroll */
header.elementor-location-header {
    position: sticky !important;
    top: 0 !important;
    z-index: 9999 !important;
    background-color: rgba(255, 255, 255, 0.98) !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06) !important;
    transition: all 0.3s ease-in-out;
}

/* Responsive 3-column Carousel Utilities */
.carousel-track-3 {
    --items-visible: 1;
    display: flex;
    transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1);
    will-change: transform;
}
@media (min-width: 640px) {
    .carousel-track-3 {
        --items-visible: 2;
    }
}
@media (min-width: 1024px) {
    .carousel-track-3 {
        --items-visible: 3;
    }
}
.carousel-slide-3 {
    width: calc(100% / var(--items-visible));
    flex-shrink: 0;
    box-sizing: border-box;
}

/* ============================================================
   FLEET CAROUSEL STYLES
   ============================================================ */
.rt-fleet-carousel {
    position: relative;
    width: 100%;
    padding: 20px 0 30px;
    user-select: none;
}
.rt-carousel-viewport {
    overflow: hidden;
    width: 100%;
    padding: 10px 4px;
}
.rt-carousel-btn {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    z-index: 30;
    width: 46px;
    height: 46px;
    border-radius: 50%;
    background-color: #ffffff;
    color: #800000;
    border: 1px solid #e5e7eb;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s ease;
    padding: 0;
    outline: none;
}
.rt-carousel-btn:hover {
    background-color: #800000;
    color: #ffffff;
    border-color: #800000;
    box-shadow: 0 6px 20px rgba(128, 0, 0, 0.25);
    transform: translateY(-50%) scale(1.06);
}
.rt-carousel-btn.btn-prev {
    left: -12px;
}
.rt-carousel-btn.btn-next {
    right: -12px;
}
@media (min-width: 768px) {
    .rt-carousel-btn.btn-prev {
        left: -20px;
    }
    .rt-carousel-btn.btn-next {
        right: -20px;
    }
}
.rt-carousel-btn svg {
    width: 22px !important;
    height: 22px !important;
    max-width: 22px !important;
    max-height: 22px !important;
    flex-shrink: 0;
}

/* Fleet Card */
.rt-fleet-card {
    background: #ffffff;
    border-radius: 18px;
    border: 1px solid #f0f0f0;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
    padding: 26px 22px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    height: 100%;
    text-align: center;
    transition: all 0.3s cubic-bezier(0.25, 1, 0.5, 1);
}
.rt-fleet-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 16px 36px rgba(0, 0, 0, 0.1);
    border-color: #e5e7eb;
}
.rt-fleet-img-wrap {
    height: 170px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 16px;
    overflow: hidden;
}
.rt-fleet-img {
    max-height: 100% !important;
    max-width: 100% !important;
    width: auto !important;
    height: auto !important;
    object-fit: contain;
    transition: transform 0.3s ease;
}
.rt-fleet-card:hover .rt-fleet-img {
    transform: scale(1.05);
}
.rt-fleet-badge {
    display: inline-block;
    padding: 4px 14px;
    background-color: rgba(128, 0, 0, 0.08);
    color: #800000;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-radius: 9999px;
    margin-bottom: 8px;
}
.rt-fleet-title {
    font-family: 'Poppins', sans-serif;
    font-size: 19px !important;
    font-weight: 700 !important;
    color: #231615 !important;
    margin: 0 0 4px 0 !important;
    line-height: 1.3 !important;
}
.rt-fleet-slogan {
    font-size: 13px !important;
    color: #6b7280 !important;
    font-style: italic !important;
    margin: 0 0 14px 0 !important;
}
.rt-fleet-divider {
    width: 100%;
    height: 1px;
    background-color: #f3f4f6;
    margin: 10px 0 14px;
}
.rt-fleet-specs {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 22px;
    font-size: 14px;
    font-weight: 600;
    color: #374151;
    margin-bottom: 20px;
}
.rt-fleet-spec-item {
    display: flex;
    align-items: center;
    gap: 7px;
}
.rt-fleet-spec-item svg {
    width: 16px !important;
    height: 16px !important;
    max-width: 16px !important;
    max-height: 16px !important;
    color: #800000;
    flex-shrink: 0;
}
.rt-fleet-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    padding: 12px 20px;
    background-color: #800000;
    color: #ffffff !important;
    font-size: 13.5px;
    font-weight: 600;
    border-radius: 10px;
    text-decoration: none !important;
    transition: all 0.2s ease;
    box-shadow: 0 4px 12px rgba(128, 0, 0, 0.2);
}
.rt-fleet-btn:hover {
    background-color: #660000;
    box-shadow: 0 6px 18px rgba(128, 0, 0, 0.35);
    color: #ffffff !important;
}
.rt-fleet-btn svg {
    width: 14px !important;
    height: 14px !important;
    max-width: 14px !important;
    max-height: 14px !important;
    flex-shrink: 0;
    transition: transform 0.2s ease;
}
.rt-fleet-btn:hover svg {
    transform: translateX(3px);
}

/* Dots */
.rt-carousel-dots {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    margin-top: 22px;
}
.rt-dot {
    height: 8px;
    border-radius: 9999px;
    background-color: #d1d5db;
    border: none;
    padding: 0;
    cursor: pointer;
    transition: all 0.3s ease;
    outline: none;
}
.rt-dot.active {
    width: 30px;
    background-color: #800000;
}
.rt-dot:not(.active) {
    width: 8px;
}
.rt-dot:not(.active):hover {
    background-color: #9ca3af;
}

/* ============================================================
   TESTIMONIALS CAROUSEL STYLES
   ============================================================ */
.rt-testimonials-section {
    position: relative;
    width: 100%;
    max-width: 1360px;
    margin: 0 auto;
    padding: 10px 16px 30px;
    user-select: none;
}

/* Google Trustindex Header Badge */
.rt-ti-header-badge {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
    background: #ffffff;
    border: 1px solid #f0f0f0;
    border-radius: 18px;
    padding: 18px 26px;
    max-width: 660px;
    margin: 0 auto 30px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
}
.rt-ti-left {
    display: flex;
    align-items: center;
    gap: 16px;
}
.rt-ti-logo-google {
    width: 38px !important;
    height: 38px !important;
    max-width: 38px !important;
    max-height: 38px !important;
    flex-shrink: 0;
}
.rt-ti-score-row {
    display: flex;
    align-items: center;
    gap: 10px;
}
.rt-ti-score-text {
    font-size: 18px;
    font-weight: 800;
    letter-spacing: 0.04em;
    color: #111827;
}
.rt-ti-stars {
    display: flex;
    align-items: center;
    gap: 3px;
    color: #f59e0b;
}
.rt-ti-stars svg {
    width: 18px !important;
    height: 18px !important;
    max-width: 18px !important;
    max-height: 18px !important;
    flex-shrink: 0;
}
.rt-ti-subtext {
    font-size: 12.5px;
    color: #6b7280;
    margin-top: 3px;
    font-weight: 500;
}
.rt-ti-subtext strong {
    color: #374151;
}
.rt-ti-pill {
    font-size: 12px;
    font-weight: 700;
    color: #800000;
    background-color: rgba(128, 0, 0, 0.08);
    padding: 6px 14px;
    border-radius: 9999px;
    white-space: nowrap;
}

/* Review Card */
.rt-review-card {
    background: #ffffff;
    border-radius: 18px;
    border: 1px solid #f0f0f0;
    box-shadow: 0 4px 22px rgba(0, 0, 0, 0.06);
    padding: 24px;
